    await expect(page.getByRole('region', { name: 'Email' }).getByRole('article', { name: 'Gmail' })).toContainText('Connected')
    await page.getByRole('navigation', { name: 'Main' }).getByRole('link', { name: 'Email', exact: true }).click()
